// MQ-135: analog level on AO, threshold output on DO.
const int ANALOG_PIN = {{AO}};
const int DIGITAL_PIN = {{DO}};

void setup() {
  Serial.begin(115200);
  pinMode(DIGITAL_PIN, INPUT);
}

void loop() {
  int level = analogRead(ANALOG_PIN);
  bool triggered = digitalRead(DIGITAL_PIN) == LOW;
  Serial.print("Gas level: ");
  Serial.print(level);
  Serial.println(triggered ? "  (threshold reached)" : "");
  delay(500);
}
